<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;

Auth::requirePermission('customers.manage');$tenantId=em_require_tenant();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='customer-save'){try{$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$status=(string)($_POST['status']??'active');if($name==='')throw new RuntimeException('Cliente inválido.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-mail inválido.');if(!in_array($status,['active','inactive','blocked'],true))throw new RuntimeException('Status inválido.');$args=[$name,$phone?:null,$email?:null,trim((string)($_POST['document']??''))?:null,$status,trim((string)($_POST['internal_notes']??''))?:null];if($id)$pdo->prepare('UPDATE customers SET name=?,phone=?,email=?,document=?,status=?,internal_notes=? WHERE id=? AND tenant_id=?')->execute([...$args,$id,$tenantId]);else{$pdo->prepare('INSERT INTO customers (tenant_id,name,phone,email,document,status,internal_notes) VALUES (?,?,?,?,?,?,?)')->execute([$tenantId,...$args]);$id=(int)$pdo->lastInsertId();}Auth::audit('customer.saved','customer',(string)$id,['status'=>$status]);em_flash('ok','Cliente salvo.');em_go('customers',['edit'=>$id]);}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('customers');}}
    if($action==='points-adjust'){$id=(int)($_POST['id']??0);$points=(int)($_POST['points']??0);if($points===0){em_flash('error','Informe pontos diferentes de zero.');em_go('customers',['edit'=>$id]);}$key='adjust:'.Auth::id().':'.$id.':'.bin2hex(random_bytes(8));$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT points FROM customers WHERE id=? AND tenant_id=? FOR UPDATE');$s->execute([$id,$tenantId]);$current=$s->fetchColumn();if($current===false)throw new RuntimeException('Cliente não encontrado.');if((int)$current+$points<0)throw new RuntimeException('Saldo não pode ficar negativo.');$pdo->prepare('INSERT INTO customer_points_movements (tenant_id,customer_id,points,type,idempotency_key) VALUES (?,?,?,"adjustment",?)')->execute([$tenantId,$id,$points,$key]);$pdo->prepare('UPDATE customers SET points=points+? WHERE id=?')->execute([$points,$id]);$pdo->commit();Auth::audit('customer.points_adjusted','customer',(string)$id,['points'=>$points]);em_flash('ok','Pontos ajustados.');}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();em_flash('error',$e->getMessage());}em_go('customers',['edit'=>$id]);}
}
$editId=(int)($_GET['edit']??0);$edit=null;$recentOrders=[];$pointHistory=[];if($editId){$s=$pdo->prepare('SELECT * FROM customers WHERE id=? AND tenant_id=?');$s->execute([$editId,$tenantId]);$edit=$s->fetch()?:null;if($edit){$o=$pdo->prepare('SELECT id,channel,status,payment_status,total_cents,created_at FROM orders WHERE tenant_id=? AND customer_id=? ORDER BY id DESC LIMIT 20');$o->execute([$tenantId,$editId]);$recentOrders=$o->fetchAll();$m=$pdo->prepare('SELECT points,type,created_at FROM customer_points_movements WHERE tenant_id=? AND customer_id=? ORDER BY id DESC LIMIT 30');$m->execute([$tenantId,$editId]);$pointHistory=$m->fetchAll();}}
$q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$sql='SELECT c.*,(SELECT COUNT(*) FROM orders o WHERE o.customer_id=c.id AND o.payment_status="paid") paid_orders,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.customer_id=c.id AND o.payment_status="paid") lifetime_value FROM customers c WHERE c.tenant_id=?';$args=[$tenantId];if($q!==''){$sql.=' AND (c.name LIKE ? OR c.phone LIKE ? OR c.email LIKE ? OR c.document LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like,$like);}if(in_array($status,['active','inactive','blocked'],true)){$sql.=' AND c.status=?';$args[]=$status;}$sql.=' ORDER BY FIELD(c.status,"active","inactive","blocked"),c.id DESC LIMIT 300';$s=$pdo->prepare($sql);$s->execute($args);$customers=$s->fetchAll();em_header('Clientes e fidelidade','customers');?>
<div class="grid" style="grid-template-columns:minmax(300px,1fr) minmax(0,2fr)"><section class="card"><h2><?= $edit?'Editar cliente':'Novo cliente' ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="customer-save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="span-2">Nome<input name="name" required value="<?= Security::e($edit['name']??'') ?>"></label><label>Telefone<input name="phone" value="<?= Security::e($edit['phone']??'') ?>"></label><label>E-mail<input type="email" name="email" value="<?= Security::e($edit['email']??'') ?>"></label><label>Documento<input name="document" value="<?= Security::e($edit['document']??'') ?>"></label><label>Status<select name="status"><option value="active"<?= em_selected($edit['status']??'active','active') ?>>Ativo</option><option value="inactive"<?= em_selected($edit['status']??'','inactive') ?>>Inativo</option><option value="blocked"<?= em_selected($edit['status']??'','blocked') ?>>Bloqueado para novas vendas</option></select></label><label class="span-2">Observações internas<textarea name="internal_notes" rows="5" placeholder="Somente a equipe vê estas informações"><?= Security::e($edit['internal_notes']??'') ?></textarea></label><button class="primary span-2">Salvar</button></form><?php if($edit):?><hr style="border-color:var(--line);margin:22px 0"><h3>Pontos: <?= (int)$edit['points'] ?></h3><form method="post" class="actions"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="points-adjust"><input type="hidden" name="id" value="<?= $editId ?>"><input type="number" name="points" style="width:120px" placeholder="+10 ou -10"><button class="secondary">Ajustar pontos</button></form><?php if($pointHistory):?><div style="margin-top:12px;max-height:220px;overflow:auto"><?php foreach($pointHistory as$m):?><div style="padding:7px 0;border-bottom:1px solid var(--line)"><strong><?= (int)$m['points']>0?'+':'' ?><?= (int)$m['points'] ?></strong> · <?= Security::e($m['type']) ?><br><small class="muted"><?= Security::e($m['created_at']) ?></small></div><?php endforeach;?></div><?php endif;?><?php endif;?></section><section class="card"><div class="section-head"><form method="get" class="actions"><input type="hidden" name="route" value="customers"><input name="q" value="<?= Security::e($q) ?>" placeholder="Nome, telefone, e-mail ou documento"><select name="status"><option value="">Todos os status</option><option value="active"<?= em_selected($status,'active') ?>>Ativos</option><option value="inactive"<?= em_selected($status,'inactive') ?>>Inativos</option><option value="blocked"<?= em_selected($status,'blocked') ?>>Bloqueados</option></select><button class="secondary">Buscar</button></form><?php if(Auth::can('exports.view')):?><a class="button secondary" href="<?= Security::e(em_url('/?route=export&kind=customers')) ?>">Exportar CSV</a><?php endif;?></div><div class="table-wrap"><table class="table"><thead><tr><th>Cliente</th><th>Status</th><th>Pedidos pagos</th><th>Valor histórico</th><th>Pontos</th><th></th></tr></thead><tbody><?php foreach($customers as$c):?><tr><td><strong><?= Security::e($c['name']) ?></strong><br><span class="muted"><?= Security::e(trim(($c['phone']??'').' '.($c['email']??''))) ?></span></td><td><span class="badge <?= $c['status']==='active'?'active':'' ?>"><?= Security::e(match($c['status']){'active'=>'Ativo','inactive'=>'Inativo','blocked'=>'Bloqueado',default=>$c['status']}) ?></span></td><td><?= (int)$c['paid_orders'] ?></td><td><?= em_money($c['lifetime_value']) ?></td><td><strong><?= (int)$c['points'] ?></strong></td><td><a class="button secondary" href="<?= Security::e(em_url('/?route=customers&edit='.(int)$c['id'])) ?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div><?php if($edit):?><hr style="border-color:var(--line);margin:22px 0"><h2>Histórico de <?= Security::e($edit['name']) ?></h2><div class="table-wrap"><table class="table"><thead><tr><th>Pedido</th><th>Canal</th><th>Status</th><th>Pagamento</th><th>Total</th><th>Data</th></tr></thead><tbody><?php foreach($recentOrders as$o):?><tr><td>#<?= (int)$o['id'] ?></td><td><?= Security::e($o['channel']) ?></td><td><?= Security::e(em_status_label($o['status'])) ?></td><td><?= Security::e(em_status_label($o['payment_status'])) ?></td><td><?= em_money($o['total_cents']) ?></td><td><?= Security::e($o['created_at']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div><?php em_footer();
